INSERT INTO "npc_spawners" VALUES (20980, 1, '18650: 칠흑의 얼음 마법서', '보스몬스터 14330 가 소환하는 몬스터. 보스가 가하는 화염 피해를 증폭시키는 얼음계열 마법주문을 사용합니다. 개체의 체력은 매우 약한 편이므로 단숨에 제거하면 피해를 받지 않을 수 있습니다.', 1, 0.0, 0.0, 0.0, 10.0, 't', 'f', 0, 3.0, 0.0, 0, 10.0);
