INSERT INTO "npc_spawners" VALUES (20989, 1, '18659: 보급품 수색병', '피난민 중에 섞여 옵니다. 몬스터가 오면 맞서 싸우기는 하지만 히라마 족 병사보다 여러모로 약합니다. 피난민처럼 동굴 안으로 피신하는 인원으로 분류됩니다.', 1, 0.0, 0.0, 0.0, 10.0, 't', 'f', 0, 3.0, 0.0, 0, 10.0);
