INSERT INTO "npc_spawners" VALUES (21038, 1, '18697: 보급품 하역소', '마법 계열 공격과 육탄전을 섞어서 사용하는 설인입니다.', 1, 0.0, 0.0, 0.0, 10.0, 't', 'f', 0, 3.0, 0.0, 0, 10.0);
INSERT INTO "npc_spawners" VALUES (21039, 1, '18698: 고대 히라마 늑대 우두머리', '■전투 : 근접. 원거리에서 도약하여 덮쳐 넘어트린뒤, 넘어진 대상을 상대로 목덜미 물어뜯기를 사용하여 경동맥 출혈을 일으킴. 도약할 거리를 만들기 위해 전투중 일부러 거리를 벌릴 때도 있음. 전투 시작 기술로 넓은 범위의 늑대에게 각개어그로를 돌림.
INSERT INTO "npc_spawners" VALUES (21040, 1, '18699: 다루루', '다루루의 신비한 선물 상자 이벤트', 1, 0.0, 0.0, 0.0, 10.0, 't', 'f', 0, 3.0, 0.0, 0, 10.0);
