INSERT INTO "npc_spawners" VALUES (21042, 1, '18701: 데인', '음식 상인', 1, 0.0, 0.0, 0.0, 10.0, 't', 'f', 0, 3.0, 0.0, 0, 10.0);
INSERT INTO "npc_spawners" VALUES (21043, 1, '18702: 보급품 수색대장', '■비전투중에는 은신 기술을 사용하여 돌아다닙니다. 이니셜 버프로 광범위한 지역에 같은 설녀를 제외한 모든 캐릭터에게 주기적인 마법 피해를 입히며, 전투에 돌입하면 광역에 피해를 입히는 기술을 사용합니다. 치유 기술을 사용하여 체력을 최고까지 채워주면 사라집니다.', 1, 0.0, 0.0, 0.0, 10.0, 't', 'f', 0, 3.0, 0.0, 0, 10.0);
