-- ----------------------------
-- Table structure for npc_spawners
-- ----------------------------
DROP TABLE IF EXISTS "npc_spawners";
CREATE TABLE "npc_spawners" (
  "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
  "npc_spawner_category_id" integer NOT NULL DEFAULT 0,
  "name" varchar(128) NOT NULL DEFAULT 'Spawner',
  "comment" varchar(255) NOT NULL DEFAULT '',
  "maxPopulation" integer NOT NULL DEFAULT 1,
  "startTime" float NOT NULL DEFAULT 0.0,
  "endTime" float NOT NULL DEFAULT 0.0,
  "destroyTime" float NOT NULL DEFAULT 0.0,
  "spawn_delay_min" float NOT NULL DEFAULT 10.0,
  "activation_state" boolean NOT NULL DEFAULT 't',
  "save_indun" boolean NOT NULL DEFAULT 'f',
  "min_population" integer NOT NULL DEFAULT 0,
  "test_radius_npc" float NOT NULL DEFAULT 3.0,
  "test_radius_pc" float NOT NULL DEFAULT 0.0,
  "suspend_spawn_count" integer NOT NULL DEFAULT 0,
  "spawn_delay_max" float NOT NULL DEFAULT 10
);

